		# Параметры движения
		self.MIN_SPEED = 0.5
		self.MAX_SPEED = 4.0
		self.TARGET_X = WIDTH + 100  # Правая граница за экраном
		self.TARGET_Y = HEIGHT + 100  # Нижняя граница за экраном
		self.VISIBILITY_MARGIN = 200  # Зона отрисовки за границами
		
		# Параметры вращения
		self.MIN_ROTATION = -0.05
