class Synth:
	SAMPLE_RATE = 44100
	BIT_DEPTH = 16
	
	def __init__(self):
		pygame.mixer.init(
			frequency=self.SAMPLE_RATE,
			size=-self.BIT_DEPTH,
			channels=2
		)
	
	def generate_wave(self, wave_type, frequency=440, duration=0.1, volume=0.5, duty_cycle=0.5):
		"""Генерирует звуковую волну заданного типа"""
		samples = np.arange(int(duration * self.SAMPLE_RATE))
		
		if wave_type == "WaveType.NOISE":
			wave = np.random.uniform(-1, 1, len(samples))
		elif wave_type == "WaveType.PULSE_12":
			wave = np.where(np.sin(2 * np.pi * frequency * samples / self.SAMPLE_RATE) > 0.75, 1, -1)
		elif wave_type == "WaveType.PULSE_25":
			wave = np.where(np.sin(2 * np.pi * frequency * samples / self.SAMPLE_RATE) > 0.5, 1, -1)
		elif wave_type == "WaveType.SQUARE":
			wave = np.where(np.sin(2 * np.pi * frequency * samples / self.SAMPLE_RATE) > 0, 1, -1)
		else:  # WaveType.SINE
			wave = np.sin(2 * np.pi * frequency * samples / self.SAMPLE_RATE)
		
		# Нормализация и применение громкости
		wave = np.clip(wave * (2**(self.BIT_DEPTH-1)-1) * volume, 
					  -(2**(self.BIT_DEPTH-1)), 
					   (2**(self.BIT_DEPTH-1)-1))
		
		# Конвертация в стерео
		stereo_wave = np.column_stack((wave.astype(np.int16), 
									  wave.astype(np.int16)))
		
		return pygame.sndarray.make_sound(stereo_wave)

class SFX:
	def __init__(self, synth):
		self.synth = synth
		
		# Звуки
		self.click_sound1 = synth.generate_wave("WaveType.PULSE_12", 1200, 0.05, 0.2, 0.5)
		self.click_sound2 = synth.generate_wave("WaveType.PULSE_12", 1568, 0.05, 0.2, 0.5)
		self.click_sound3 = synth.generate_wave("WaveType.NOISE", 700, 0.05, 0.2, 0.5)
		self.win_sound = synth.generate_wave("WaveType.PULSE_12", 2093, 0.05, 0.2, 0.5)
		self.victory_sound1 = synth.generate_wave("WaveType.PULSE_12", 784, 0.1, 0.2, 0.5)
		self.victory_sound2 = synth.generate_wave("WaveType.PULSE_12", 1046, 0.1, 0.2, 0.5)
		self.victory_sound3 = synth.generate_wave("WaveType.PULSE_12", 1318, 0.1, 0.2, 0.5)
		self.victory_sound4 = synth.generate_wave("WaveType.PULSE_12", 1568, 0.1, 0.2, 0.5)
		self.death_sound = synth.generate_wave("WaveType.PULSE_12", 1200, 0.1, 0.2, 0.5)
		self.teleport_sound1 = synth.generate_wave("WaveType.SQUARE", 900, 0.05, 0.2, 0.5)
		self.teleport_sound2 = synth.generate_wave("WaveType.PULSE_25", 1000, 0.05, 0.2, 0.5)
		self.pistol_shot1 = synth.generate_wave("WaveType.NOISE", 600, 0.05, 0.2, 0.5)
		self.pistol_shot2 = synth.generate_wave("WaveType.NOISE", 400, 0.05, 0.2, 0.5)
		self.reload_sound = synth.generate_wave("WaveType.PULSE_25", 440, 0.05, 0.2, 0.5)
		
		# Очередь звуков
		self.sound_queue = []
	
	def play_sound(self, sound):
		"""Воспроизведение одиночного звука"""
		sound.play()
	
	def play(self, sound_key):
		"""Запуск последовательности звуков"""
		current_time = time.time()
		match sound_key:
			case "click_sound":
				self.sound_queue.append({"sound": self.click_sound1, "play_time": current_time})
				self.sound_queue.append({"sound": self.click_sound2, "play_time": current_time + 0.05})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.05})
			case "win_sound":
				self.sound_queue.append({"sound": self.click_sound1, "play_time": current_time})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time})
				self.sound_queue.append({"sound": self.click_sound2, "play_time": current_time + 0.05})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.05})
				self.sound_queue.append({"sound": self.win_sound, "play_time": current_time + 0.10})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.10})
			case "exit_sound":
				self.sound_queue.append({"sound": self.click_sound1, "play_time": current_time})
				self.sound_queue.append({"sound": self.click_sound1, "play_time": current_time + 0.08})
				self.sound_queue.append({"sound": self.click_sound1, "play_time": current_time + 0.16})
			case "victory_sound":
				self.sound_queue.append({"sound": self.victory_sound1, "play_time": current_time})
				self.sound_queue.append({"sound": self.victory_sound2, "play_time": current_time + 0.10})
				self.sound_queue.append({"sound": self.victory_sound3, "play_time": current_time + 0.20})
				self.sound_queue.append({"sound": self.victory_sound4, "play_time": current_time + 0.30})
				self.sound_queue.append({"sound": self.victory_sound3, "play_time": current_time + 0.50})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.50})
				self.sound_queue.append({"sound": self.victory_sound4, "play_time": current_time + 0.60})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.60})
			case "death_sound":
				self.sound_queue.append({"sound": self.death_sound, "play_time": current_time})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time})
			case "key_sound":
				self.sound_queue.append({"sound": self.click_sound2, "play_time": current_time})
				self.sound_queue.append({"sound": self.click_sound1, "play_time": current_time + 0.10})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.10})
				self.sound_queue.append({"sound": self.win_sound, "play_time": current_time + 0.20})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.20})
			case "teleport_sound":
				self.sound_queue.append({"sound": self.teleport_sound1, "play_time": current_time})
				self.sound_queue.append({"sound": self.teleport_sound2, "play_time": current_time + 0.07})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.07})
			case "pistol_pickup":
				self.sound_queue.append({"sound": self.teleport_sound1, "play_time": current_time})
				self.sound_queue.append({"sound": self.click_sound1, "play_time": current_time + 0.07})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.07})
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time + 0.17})
			case "pistol_shot":
				self.sound_queue.append({"sound": self.click_sound3, "play_time": current_time})
				self.sound_queue.append({"sound": self.pistol_shot1, "play_time": current_time + 0.03})
				self.sound_queue.append({"sound": self.pistol_shot2, "play_time": current_time + 0.06})
			case "reload_sound":
				self.sound_queue.append({"sound": self.pistol_shot1, "play_time": current_time})
				self.sound_queue.append({"sound": self.reload_sound, "play_time": current_time})
	
	def update(self):
		"""Обновление очереди звуков"""
		current_time = time.time()
		for sound in self.sound_queue[:]:  # Копируем список для безопасного удаления
			if current_time >= sound["play_time"]:
				self.play_sound(sound["sound"])
				self.sound_queue.remove(sound)

