# Класс для анимированного заголовка
class TitleAnimation:
	def __init__(self):
		self.font = title_font
		self.text = "fallen_atom"
		self.current_text = ""
		self.last_char_time = 0
		self.char_delay = 0.1
		self.complete = False
	
	def update(self):
		if not self.complete and time.time() - self.last_char_time > self.char_delay:
			if len(self.current_text) < len(self.text):
				self.current_text += self.text[len(self.current_text)]
				self.last_char_time = time.time()
			else:
				self.complete = True
	
	def draw(self, surface):
		text_surf = self.font.render(self.current_text, True, (255, 255, 255))
		surface.blit(text_surf, (WIDTH//2 - text_surf.get_width()//2, HEIGHT//2 - 100))

class Button:
	def __init__(self, x, y, text, padding_x=50, padding_y=15):
		self.font = game_font
		self.text = str(text)
		self.text_surf_normal = self.font.render(self.text, True, (255, 255, 255))  # Белый текст
		self.text_surf_hover = self.font.render(self.text, True, (0, 0, 0))         # Чёрный текст
		self.text_rect = self.text_surf_normal.get_rect()
		
		# Размер кнопки с учетом отступов
		self.width = self.text_rect.width + padding_x * 2
		self.height = self.text_rect.height + padding_y * 2
		self.rect = pygame.Rect(x - self.width//2, y - self.height//2, self.width, self.height)
		
		self.hovered = False
	
	def draw(self, surface):
		if self.hovered:
			# Состояние наведения: чёрный текст без рамки
			pygame.draw.rect(surface, (30, 255, 30), self.rect)  # Зелёный фон
			text_x = self.rect.centerx - self.text_rect.width // 2
			text_y = self.rect.centery - self.text_rect.height // 2
			surface.blit(self.text_surf_hover, (text_x, text_y))
		else:
			# Нормальное состояние: белый текст с белой рамкой
			pygame.draw.rect(surface, (0, 0, 0), self.rect)  # Чёрный фон
			pygame.draw.rect(surface, (255, 255, 255), self.rect, 2)  # Белая рамка (толщина 2px)
			text_x = self.rect.centerx - self.text_rect.width // 2
			text_y = self.rect.centery - self.text_rect.height // 2
			surface.blit(self.text_surf_normal, (text_x, text_y))
	
	def check_hover(self, pos):
		self.hovered = self.rect.collidepoint(pos)
		return self.hovered

	def update_text(self, x, y):
		# Обновляем текст и поверхности
		self.text_surf_normal = self.font.render(self.text, True, (255, 255, 255))
		self.text_surf_hover = self.font.render(self.text, True, (0, 0, 0))
		self.text_rect = self.text_surf_normal.get_rect()
		
		# Пересчитываем размер и положение кнопки
		self.width = self.text_rect.width + 50 * 2  # Используем padding_x из __init__
		self.height = self.text_rect.height + 15 * 2  # Используем padding_y из __init__
		self.rect = pygame.Rect(x - self.width//2, y - self.height//2, self.width, self.height)

# Функция для воспроизведения MP3 из Base64
def play_mp3_from_base64(mp3_b64):
	try:
		mp3_data = base64.b64decode(mp3_b64)
		mp3_file = io.BytesIO(mp3_data)
		audio = AudioSegment.from_mp3(mp3_file)
		wav_data = io.BytesIO()
		audio.export(wav_data, format="wav")
		wav_data.seek(0)
		pygame.mixer.init(frequency=22050, size=-16, channels=2)
		pygame.mixer.music.load(wav_data)
		pygame.mixer.music.play(loops=-1)
	except Exception as e:
		print(f"Ошибка воспроизведения музыки: {e}")

def create_square():
	size = random.randint(settings.MIN_SIZE, settings.MAX_SIZE)
	spawn_side = random.randint(0, 3)
	
	if spawn_side == 0:  # Левая
		x = random.randint(-settings.SPAWN_MARGIN, -size)
		y = random.randint(-settings.SPAWN_MARGIN, HEIGHT + settings.SPAWN_MARGIN)
	elif spawn_side == 1:  # Правая
		x = random.randint(WIDTH + size, WIDTH + settings.SPAWN_MARGIN)
		y = random.randint(-settings.SPAWN_MARGIN, HEIGHT + settings.SPAWN_MARGIN)
	elif spawn_side == 2:  # Верх
		x = random.randint(-settings.SPAWN_MARGIN, WIDTH + settings.SPAWN_MARGIN)
		y = random.randint(-settings.SPAWN_MARGIN, -size)
	else:  # Низ
		x = random.randint(-settings.SPAWN_MARGIN, WIDTH + settings.SPAWN_MARGIN)
		y = random.randint(HEIGHT + size, HEIGHT + settings.SPAWN_MARGIN)
	
	return {
		'x': x, 'y': y, 'size': size,
		'speed': random.uniform(settings.MIN_SPEED, settings.MAX_SPEED),
		'hue': random.random(),
		'angle': 0,
		'rotation': random.uniform(settings.MIN_ROTATION, settings.MAX_ROTATION),
		'trail': []
	}

def update_square(square):
	# Движение к цели
	dx = settings.TARGET_X - square['x']
	dy = settings.TARGET_Y - square['y']
	distance = max(1, math.sqrt(dx*dx + dy*dy))
	
	square['x'] += (dx/distance) * square['speed']
	square['y'] += (dy/distance) * square['speed']
	
	# Обновление состояния
	square['angle'] += square['rotation']
	square['trail'].append((square['x'], square['y'], square['size'], square['hue'], square['angle']))
	if len(square['trail']) > settings.TRAIL_LENGTH:
		square['trail'].pop(0)
	
	square['hue'] = (square['hue'] + settings.HUE_CHANGE_SPEED) % 1.0
	
	# Проверка видимости (с учетом размера)
	half_size = square['size'] * settings.SIZE_RATIO
	return not (
		square['x'] > WIDTH + half_size and 
		square['y'] > HEIGHT + half_size
	)

def draw_rotated_square(surface, x, y, size, angle, color):
	points = []
	half_size = size * settings.SIZE_RATIO
	for i in range(4):
		point_angle = angle + i * math.pi/2
		px = x + half_size * math.cos(point_angle)
		py = y + half_size * math.sin(point_angle)
		points.append((px, py))
	
	# Для прозрачных элементов (след)
	if len(color) == 4:  # Если цвет с альфа-каналом (RGBA)
		temp_surface = pygame.Surface((size*2, size*2), pygame.SRCALPHA)
		pygame.draw.polygon(temp_surface, color, points, 2)  # Только контур
		surface.blit(temp_surface, (x - size, y - size))
	else:  # Для непрозрачных (основные квадраты)
		pygame.draw.polygon(surface, color, points, 2)  # Только контур

def draw_square(surface, square):
	# Упрощенная проверка видимости - только по центру квадрата
	size = square['size']
	if not (-size < square['x'] < WIDTH + size and 
			-size < square['y'] < HEIGHT + size):
		return
	
	# Отрисовка следа
	trail_count = len(square['trail'])
	for i, (tx, ty, tsize, thue, tangle) in enumerate(square['trail']):
		alpha = int(settings.TRAIL_ALPHA_MAX * (i/trail_count))
		r, g, b, a = hsv_to_rgb(thue * 360, settings.SATURATION, settings.BRIGHTNESS, alpha)
		
		# Создаем временную поверхность для каждого элемента следа
		temp_surface = pygame.Surface((tsize*3, tsize*3), pygame.SRCALPHA)
		points = []
		half_size = tsize * settings.SIZE_RATIO
		for j in range(4):
			angle = tangle + j * math.pi/2
			px = tsize + half_size * math.cos(angle)
			py = tsize + half_size * math.sin(angle)
			points.append((px, py))
		
		pygame.draw.polygon(temp_surface, (r, g, b, a), points, 2)
		surface.blit(temp_surface, (tx - tsize, ty - tsize))
	
	# Отрисовка основного квадрата
	hue = square['hue'] * 360
	r, g, b = hsv_to_rgb(hue, settings.SATURATION, settings.BRIGHTNESS, 255)[:3]
	points = []
	half_size = size * settings.SIZE_RATIO
	for i in range(4):
		angle = square['angle'] + i * math.pi/2
		px = square['x'] + half_size * math.cos(angle)
		py = square['y'] + half_size * math.sin(angle)
		points.append((px, py))
	
	pygame.draw.polygon(surface, (r, g, b), points, 2)

def hsv_to_rgb(h, s, v, a):
	h = h % 360
	s = min(max(s, 0), 100) / 100.0
	v = min(max(v, 0), 100) / 100.0
	a = min(max(a, 0), 255)
	
	c = v * s
	x = c * (1 - abs((h / 60) % 2 - 1))
	m = v - c
	
	if 0 <= h < 60:
		r, g, b = c, x, 0
	elif 60 <= h < 120:
		r, g, b = x, c, 0
	elif 120 <= h < 180:
		r, g, b = 0, c, x
	elif 180 <= h < 240:
		r, g, b = 0, x, c
	elif 240 <= h < 300:
		r, g, b = x, 0, c
	else:
		r, g, b = c, 0, x
		
	return (
		int((r + m) * 255),
		int((g + m) * 255),
		int((b + m) * 255),
		int(a)
	)

