# Модифицированный класс Player:
class Player:
	def __init__(self, x, y):
		self.x = x
		self.y = y
		self.rect = pygame.Rect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE)
		self.current_speed_x = 0
		self.current_speed_y = 0
		self.settings = settings  # Ссылка на настройки
		self.last_dx = 0  # Последнее направление по X
		self.last_dy = 0  # Последнее направление по Y
		self.has_pistol = False  # Есть ли пистолет
		self.ammo_in_clip = 0  # Патроны в магазине
		self.total_ammo = 0  # Общие патроны
		self.reloading = False  # Флаг перезарядки
		self.reload_start_time = 0  # Время начала перезарядки
	
	def update(self, dx, dy, walls, gates1, gates2, gates3, dt):
		# Плавное изменение скорости
		self.current_speed_x = self.accelerate(self.current_speed_x, dx, dt)
		self.current_speed_y = self.accelerate(self.current_speed_y, dy, dt)
		
		# Сохраняем последнее направление, если оно не нулевое
		if dx != 0 or dy != 0:
			self.last_dx = dx
			self.last_dy = dy
		
		move_x = self.current_speed_x * dt * TILE_SIZE
		move_y = self.current_speed_y * dt * TILE_SIZE
		
		new_rect = self.rect.move(move_x, move_y)
		if not (any(new_rect.colliderect(wall.rect) for wall in walls) or
				any(new_rect.colliderect(gate.rect) for gate in gates1) or
				any(new_rect.colliderect(gate.rect) for gate in gates2) or
				any(new_rect.colliderect(gate.rect) for gate in gates3)):
			self.rect = new_rect
			return True
		return False
	
	def accelerate(self, current, direction, dt):
		target = direction * self.settings.PLAYER_MAX_SPEED
		if current < target:
			return min(target, current + self.settings.PLAYER_ACCELERATION * dt)
		elif current > target:
			return max(target, current - self.settings.PLAYER_DECELERATION * dt)
		return target

	def shoot(self, bullets, current_time):
		if not self.has_pistol or self.reloading or self.ammo_in_clip <= 0:
			return False
		start_x = self.rect.centerx + self.last_dx * TILE_SIZE
		start_y = self.rect.centery + self.last_dy * TILE_SIZE
		bullets.append(PistolBullet(start_x, start_y, self.last_dx, self.last_dy))
		self.ammo_in_clip -= 1
		if self.ammo_in_clip == 0 and self.total_ammo > 0:
			self.reload(current_time)
		return True
	
	def reload(self, current_time):
		if not self.has_pistol or self.total_ammo <= 0 or self.reloading or self.ammo_in_clip >= settings.PISTOL_MAX_AMMO:
			return False
		self.reloading = True
		self.reload_start_time = current_time
		if sfx:
			sfx.play("reload_sound")
			sfx.update()
		return True
	
	def update_reload(self, current_time):
		if self.reloading and current_time - self.reload_start_time >= settings.PISTOL_RELOAD_TIME:
			ammo_to_reload = min(settings.PISTOL_MAX_AMMO - self.ammo_in_clip, self.total_ammo)
			self.ammo_in_clip += ammo_to_reload
			self.total_ammo -= ammo_to_reload
			self.reloading = False
			return True
		return False

	def get_reload_progress(self, current_time):
		"""Возвращает прогресс перезарядки (0.0 - 1.0) и оставшееся время в секундах"""
		if not self.reloading:
			return 0.0, 0.0
		elapsed = current_time - self.reload_start_time
		progress = min(1.0, elapsed / settings.PISTOL_RELOAD_TIME)
		remaining_time = max(0.0, settings.PISTOL_RELOAD_TIME - elapsed)
		return progress, remaining_time

