class Enemy:
	def __init__(self, x, y):
		self.rect = pygame.Rect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE)
		self.shoot_timer = 0
	
	def update(self, dt, bullets, player_x, player_y):
		self.shoot_timer += dt
		if self.shoot_timer >= settings.ENEMY_SHOOT_DELAY:
			self.shoot_timer = 0
			self.shoot(bullets, player_x, player_y)
	
	def shoot(self, bullets, player_x, player_y):
		# Вычисляем разницу координат между врагом и игроком
		dx = player_x - self.rect.centerx
		dy = player_y - self.rect.centery
		
		# Определяем основное направление
		if abs(dx) > abs(dy):
			# Горизонтальное направление доминирует
			direction = (1, 0) if dx > 0 else (-1, 0)  # Вправо или влево
		else:
			# Вертикальное направление доминирует
			direction = (0, 1) if dy > 0 else (0, -1)  # Вниз или вверх
		
		dx, dy = direction
		start_x = self.rect.centerx + dx * TILE_SIZE
		start_y = self.rect.centery + dy * TILE_SIZE
		bullets.append(Bullet(start_x, start_y, dx, dy))

