class Bullet:
	def __init__(self, x, y, dx, dy):
		self.rect = pygame.Rect(x - settings.BULLET_SIZE//2, 
							   y - settings.BULLET_SIZE//2, 
							   settings.BULLET_SIZE, 
							   settings.BULLET_SIZE)
		self.dx = dx * 5
		self.dy = dy * 5
		self.color = (255, 100, 100)
	
	def update(self, walls, barriers, gates1, gates2, gates3, enemies):
		next_rect = self.rect.move(self.dx, self.dy)
		if (any(next_rect.colliderect(wall.rect) for wall in walls) or
			any(next_rect.colliderect(barrier.rect) for barrier in barriers) or
			any(next_rect.colliderect(gate.rect) for gate in gates1) or
			any(next_rect.colliderect(gate.rect) for gate in gates2) or
			any(next_rect.colliderect(gate.rect) for gate in gates3) or
			any(next_rect.colliderect(enemy.rect) for enemy in enemies)):
			return True  # Пуля уничтожается при столкновении с любым врагом
		
		self.rect = next_rect
		return False

