class Death:
	def __init__(self, language):
		self.start_time = time.time()
		self.duration = 3.0  # 3 секунды
		self.font = title_font
		self.message = language["you_died"]
		self.alpha = 0
		
	def update(self):
		current_time = time.time()
		elapsed = current_time - self.start_time
		
		# Плавное появление и исчезание эффекта
		if elapsed < self.duration / 2:
			self.alpha = min(255, self.alpha + 10)
		else:
			self.alpha = max(0, self.alpha - 10)
			
		return elapsed >= self.duration
	
	def draw(self, surface):
		# Создаем поверхность для эффекта затемнения
		overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
		overlay.fill((255, 0, 0, self.alpha // 2))  # Красный с прозрачностью
		
		# Отрисовываем текст
		text_surf = self.font.render(self.message, True, (255, 255, 255, self.alpha))
		text_rect = text_surf.get_rect(center=(WIDTH//2, HEIGHT//2))
		
		surface.blit(overlay, (0, 0))
		surface.blit(text_surf, text_rect)
	
	def run(self):
		self.start_time = time.time()
		self.alpha = 0
		
		# Ждем завершения эффекта смерти
		clock = pygame.time.Clock()
		running = True
		while running:
			dt = clock.tick(60) / 1000.0
			
			for event in pygame.event.get():
				if event.type == pygame.QUIT:
					pygame.quit()
					return
			
			# Обновляем эффект
			if self.update():
				running = False
			
			# Отрисовываем текущий кадр
			screen.fill((0, 0, 0))
			
			# Отрисовываем эффект смерти
			self.draw(screen)
			
			pygame.display.flip()

class LevelDrawer:
	def __init__(self, level_pattern, language, level_num):
		self.walls = []
		self.fake_walls = []
		self.goals = []
		self.enemies = []
		self.barriers = []
		self.bullets = []
		self.coins = []
		self.gates1 = []
		self.gates2 = []
		self.gates3 = []
		self.teleports_i = []  # Пара телепортов 'i'
		self.teleports_o = []  # Пара телепортов 'o'
		self.teleports_l = []  # Пара телепортов 'l'
		self.pistols = []  # Массив пистолетов
		self.player_bullets = []  # Пули игрока
		self.key1 = None
		self.key2 = None
		self.key3 = None
		self.has_key1 = False
		self.has_key2 = False
		self.has_key3 = False
		self.spawn = None
		self.player = None
		self.teleported = False
		self.language = language
		self.level_num = level_num
		self.comments = getattr(level_pattern, 'comments', None)  # Получаем комментарии если они есть
		self.parse_level(level_pattern.pattern if hasattr(level_pattern, 'pattern') else level_pattern)
		
		# Настройки камеры
		self.camera_x = 0
		self.camera_y = 0
		self.game_area = pygame.Rect(50, 50, WIDTH - 100, HEIGHT - 100)
		self.update_comments()
	
	def parse_level(self, pattern):
		for y, row in enumerate(pattern):
			for x, char in enumerate(row):
				if char == 'w':
					self.walls.append(Wall(x, y))
				elif char == 'g':
					self.goals.append(Goal(x, y))
				elif char == 's':
					self.spawn = SpawnPoint(x, y)
					self.player = Player(x, y)
				elif char == 'e':
					self.enemies.append(Enemy(x, y))
				elif char == 'b':
					self.barriers.append(Barrier(x, y))
				elif char == 'c':
					self.coins.append(Coin(x, y))
				elif char == 'x':
					self.gates1.append(Gate(x, y))
				elif char == 'y':
					self.gates2.append(Gate(x, y))
				elif char == 'z':
					self.gates3.append(Gate(x, y))
				elif char == '1':
					self.key1 = Key(x, y)
				elif char == '2':
					self.key2 = Key(x, y)
				elif char == '3':
					self.key3 = Key(x, y)
				elif char == 'f':
					self.fake_walls.append(FakeWall(x, y))
				elif char == 'i':
					self.teleports_i.append(Teleport(x, y, 'i'))
				elif char == 'o':
					self.teleports_o.append(Teleport(x, y, 'o'))
				elif char == 'l':
					self.teleports_l.append(Teleport(x, y, 'l'))
				elif char == 'p':
					self.pistols.append(Pistol(x, y))  # Добавляем каждый пистолет в массив

	def update_comments(self):
		# Устанавливаем комментарии по номеру уровня
		self.comments = self.language.get(f"level{self.level_num}", "")
	
	def draw_comments(self, surface):
		# Разбиваем комментарии на строки
		lines = self.comments.split('\n')
		padding = 15
		line_height = game_font.get_height()
		
		# Рассчитываем общую высоту текстового блока
		total_height = len(lines) * line_height + (len(lines) - 1) * 5  # 5 - отступ между строками
		
		# Позиция для отрисовки (правый нижний угол)
		y_pos = HEIGHT - padding - total_height
		
		# Рендерим строки снизу вверх
		for i, line in enumerate(reversed(lines)):
			text_surface = game_font.render(line, True, (255, 255, 255))  # Белый текст
			x_pos = WIDTH - text_surface.get_width() - padding
			surface.blit(text_surface, (x_pos, y_pos + (len(lines)-1-i) * (line_height + 5)))

	def _draw_border_vignette(self, surface):
		"""Отрисовывает затенение у границ игровой области (тёмное у краёв)"""
		border_size = 35  # Ширина затенения от краёв
		rect = self.game_area
		
		# Создаём поверхность размером с игровую область
		overlay = pygame.Surface((rect.w, rect.h), pygame.SRCALPHA)
		
		# Горизонтальные градиенты (верх и низ)
		for y in [0, rect.h - border_size]:
			gradient = pygame.Surface((rect.w, border_size), pygame.SRCALPHA)
			for i in range(border_size):
				alpha = int(255 * (1 - i/border_size))  # Ключевое изменение: 1 - i/border_size
				pygame.draw.line(
					gradient,
					(0, 0, 0, alpha),  # Чёрный с изменяющейся прозрачностью
					(0, i if y == 0 else border_size - i - 1),
					(rect.w, i if y == 0 else border_size - i - 1)
				)
			overlay.blit(gradient, (0, y))
		
		# Вертикальные градиенты (лево и право)
		for x in [0, rect.w - border_size]:
			gradient = pygame.Surface((border_size, rect.h), pygame.SRCALPHA)
			for i in range(border_size):
				alpha = int(180 * (1 - i/border_size))  # Аналогичное изменение
				pygame.draw.line(
					gradient,
					(0, 0, 0, alpha),
					(i if x == 0 else border_size - i - 1, 0),
					(i if x == 0 else border_size - i - 1, rect.h)
				)
			overlay.blit(gradient, (x, 0))
		
		# Накладываем на игровую область
		surface.blit(overlay, (rect.x, rect.y))

	def draw(self, surface, level_num):
		pygame.draw.rect(surface, BG_COLOR, self.game_area)
		old_clip = surface.get_clip()
		surface.set_clip(self.game_area)
		
		camera_offset = (
			-self.camera_x + self.game_area.x,
			-self.camera_y + self.game_area.y
		)
		
		for wall in self.walls:
			adjusted_rect = wall.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, WALL_COLOR, adjusted_rect)

		for fake_wall in self.fake_walls:
			adjusted_rect = fake_wall.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, WALL_COLOR, adjusted_rect)
		
		for goal in self.goals:
			adjusted_rect = goal.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, GOAL_COLOR, adjusted_rect)
		
		for enemy in self.enemies:
			adjusted_rect = enemy.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, ENEMY_COLOR, adjusted_rect)
		
		for coin in self.coins:
			adjusted_rect = coin.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, COIN_COLOR, adjusted_rect)
		
		for barrier in self.barriers:
			adjusted_rect = barrier.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, ENEMY_COLOR, adjusted_rect)
		
		# Отрисовка ворот только если ключ не подобран
		if not self.has_key1:
			for gate in self.gates1:
				adjusted_rect = gate.rect.move(camera_offset[0], camera_offset[1])
				pygame.draw.rect(surface, GATE_COLOR, adjusted_rect)
		if not self.has_key2:
			for gate in self.gates2:
				adjusted_rect = gate.rect.move(camera_offset[0], camera_offset[1])
				pygame.draw.rect(surface, GATE_COLOR, adjusted_rect)
		if not self.has_key3:
			for gate in self.gates3:
				adjusted_rect = gate.rect.move(camera_offset[0], camera_offset[1])
				pygame.draw.rect(surface, GATE_COLOR, adjusted_rect)
		
		if self.key1 and not self.has_key1:
			adjusted_rect = self.key1.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, KEY_COLOR, adjusted_rect)
		if self.key2 and not self.has_key2:
			adjusted_rect = self.key2.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, KEY_COLOR, adjusted_rect)
		if self.key3 and not self.has_key3:
			adjusted_rect = self.key3.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, KEY_COLOR, adjusted_rect)
		
		if self.spawn:
			adjusted_rect = self.spawn.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, SPAWN_COLOR, adjusted_rect)
		
		if self.player:
			adjusted_rect = self.player.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, PLAYER_COLOR, adjusted_rect)
			# Отображение перезарядки
			if self.player.reloading:
				progress, remaining_time = self.player.get_reload_progress(time.time())
				center_x = adjusted_rect.centerx
				center_y = adjusted_rect.top - 35  # Чуть выше игрока
				radius = 20
				# Рисуем дугу (сектор окружности)
				rect = pygame.Rect(center_x - radius, center_y - radius, radius * 2, radius * 2)
				start_angle = -math.pi / 2  # Начало сверху (12 часов)
				end_angle = start_angle + 2 * math.pi * (1 - progress)  # Уменьшается по часовой стрелке
				pygame.draw.arc(surface, PISTOL_COLOR, rect, start_angle, end_angle, 3)  # Толщина 3 пикселя
				# Рисуем текст с оставшимся временем
				time_text = f"{remaining_time:.1f}"  # Формат 1.2
				text_surf = reload_font.render(time_text, True, (255, 255, 255))
				text_rect = text_surf.get_rect(center=(center_x, center_y))
				surface.blit(text_surf, text_rect)
			# Отображение стрелки направления стрельбы
			if self.player.has_pistol:
				arrow_size = 8  # Уменьшаем размер для компактности
				arrow_color = PISTOL_COLOR  # Оранжевый
				dx, dy = self.player.last_dx, self.player.last_dy
				# Позиция стрелки чуть дальше от игрока
				distance_from_player = TILE_SIZE * 0.8
				arrow_tip_x = adjusted_rect.centerx + dx * distance_from_player
				arrow_tip_y = adjusted_rect.centery + dy * distance_from_player
				# Нормализуем направление для диагоналей
				length = max(1, (dx * dx + dy * dy) ** 0.5)  # Избегаем деления на 0
				norm_dx, norm_dy = dx / length, dy / length
				# Точки треугольника
				tip = (arrow_tip_x, arrow_tip_y)
				left_wing = (
					arrow_tip_x - norm_dx * arrow_size + norm_dy * arrow_size * 0.5,
					arrow_tip_y - norm_dy * arrow_size - norm_dx * arrow_size * 0.5
				)
				right_wing = (
					arrow_tip_x - norm_dx * arrow_size - norm_dy * arrow_size * 0.5,
					arrow_tip_y - norm_dy * arrow_size + norm_dx * arrow_size * 0.5
				)
				points = [tip, left_wing, right_wing]
				pygame.draw.polygon(surface, arrow_color, points)
		for bullet in self.bullets:
			adjusted_rect = bullet.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, bullet.color, adjusted_rect)

		for teleport in self.teleports_i:
			adjusted_rect = teleport.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, TELEPORT_COLOR, adjusted_rect)

		for teleport in self.teleports_o:
			adjusted_rect = teleport.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, TELEPORT_COLOR, adjusted_rect)

		for teleport in self.teleports_l:
			adjusted_rect = teleport.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, TELEPORT_COLOR, adjusted_rect)

		# Отрисовка всех пистолетов, которые ещё не подобраны
		for pistol in self.pistols:
			adjusted_rect = pistol.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, PISTOL_COLOR, adjusted_rect)
		
		# Отрисовка пуль игрока
		for bullet in self.player_bullets:
			adjusted_rect = bullet.rect.move(camera_offset[0], camera_offset[1])
			pygame.draw.rect(surface, bullet.color, adjusted_rect)
		
		self._draw_border_vignette(surface)
		surface.set_clip(old_clip)
		pygame.draw.rect(surface, (100, 100, 100), self.game_area, 2)
		
		level_text = game_font.render(f"{self.language['level']} {level_num}", True, (255, 255, 255))
		level_rect = level_text.get_rect(center=(400, self.game_area.y - 20))
		surface.blit(level_text, level_rect)
		
		if self.comments:
			self.draw_comments(surface)
	
	def update_camera(self):
		if self.player:
			target_x = self.player.rect.x - self.game_area.width // 2
			target_y = self.player.rect.y - self.game_area.height // 2
			self.camera_x += (target_x - self.camera_x) * settings.CAMERA_SMOOTHNESS
			self.camera_y += (target_y - self.camera_y) * settings.CAMERA_SMOOTHNESS
	
	def handle_input(self, keys, dt):
		if self.player:
			dx, dy = 0, 0
			if keys[K_LEFT] or keys[K_a]: dx = -1
			if keys[K_RIGHT] or keys[K_d]: dx = 1
			if keys[K_UP] or keys[K_w]: dy = -1
			if keys[K_DOWN] or keys[K_s]: dy = 1

			active_gates1 = self.gates1 if not self.has_key1 else []
			active_gates2 = self.gates2 if not self.has_key2 else []
			active_gates3 = self.gates3 if not self.has_key3 else []
			if self.player.update(dx, dy, self.walls, active_gates1, active_gates2, active_gates3, dt):
				self.update_camera()
	
	def check_win(self):
		if self.player and self.goals:
			return any(self.player.rect.colliderect(goal.rect) for goal in self.goals)
		return False

	def collect_coin(self):
		if not self.player or not self.coins:
			return False
		
		for i, coin in enumerate(self.coins):
			if self.player.rect.colliderect(coin.rect):
				self.coins.pop(i)
				return True
		
		return False

	def collect_key(self):
		if not self.player:
			return False
		if self.key1 and not self.has_key1 and self.player.rect.colliderect(self.key1.rect):
			self.has_key1 = True
			return True
		if self.key2 and not self.has_key2 and self.player.rect.colliderect(self.key2.rect):
			self.has_key2 = True
			return True
		if self.key3 and not self.has_key3 and self.player.rect.colliderect(self.key3.rect):
			self.has_key3 = True
			return True
		return False

	def death(self):
		if self.player and self.barriers or self.enemies:
			return any(self.player.rect.colliderect(barrier.rect) for barrier in self.barriers) or any(self.player.rect.colliderect(enemy.rect) for enemy in self.enemies)
		return False

	# Добавляем метод для проверки попадания пули в игрока
	def check_bullet_collision(self):
		if self.player:
			for bullet in self.bullets:
				if self.player.rect.colliderect(bullet.rect):
					return True
		return False
	
	def update_gameplay(self, dt):
		for enemy in self.enemies:
			enemy.update(dt, self.bullets, self.player.rect.centerx, self.player.rect.centery)
		
		active_gates1 = self.gates1 if not self.has_key1 else []
		active_gates2 = self.gates2 if not self.has_key2 else []
		active_gates3 = self.gates3 if not self.has_key3 else []
		
		for i in range(len(self.bullets) - 1, -1, -1):
			if self.bullets[i].update(self.walls, self.barriers, active_gates1, active_gates2, active_gates3, self.enemies):
				self.bullets.pop(i)

		for i in range(len(self.player_bullets) - 1, -1, -1):
			bullet = self.player_bullets[i]
			if bullet.update(self.walls, self.barriers, active_gates1, active_gates2, active_gates3):
				self.player_bullets.pop(i)
				continue
			for j in range(len(self.enemies) - 1, -1, -1):
				if bullet.rect.colliderect(self.enemies[j].rect):
					self.enemies.pop(j)
					self.player_bullets.pop(i)
					break

	def check_teleport(self):
		if not self.player:
			return False
		
		# Проверяем, находится ли игрок на каком-либо телепорте
		on_teleport = False
		all_teleports = self.teleports_i + self.teleports_o + self.teleports_l
		for teleport in all_teleports:
			if self.player.rect.colliderect(teleport.rect):
				on_teleport = True
				break
		
		# Если игрок не на телепорте, сбрасываем флаг
		if not on_teleport and self.teleported:
			self.teleported = False
		
		# Если уже телепортировались, не делаем ничего
		if self.teleported:
			return False
		
		# Проверяем телепорты 'i'
		if len(self.teleports_i) == 2:
			for i, teleport in enumerate(self.teleports_i):
				if self.player.rect.colliderect(teleport.rect):
					target = self.teleports_i[1 - i]
					self.player.rect.center = target.rect.center
					self.update_camera()
					self.teleported = True
					return True
		
		# Проверяем телепорты 'o'
		if len(self.teleports_o) == 2:
			for i, teleport in enumerate(self.teleports_o):
				if self.player.rect.colliderect(teleport.rect):
					target = self.teleports_o[1 - i]
					self.player.rect.center = target.rect.center
					self.update_camera()
					self.teleported = True
					return True
		
		# Проверяем телепорты 'l'
		if len(self.teleports_l) == 2:
			for i, teleport in enumerate(self.teleports_l):
				if self.player.rect.colliderect(teleport.rect):
					target = self.teleports_l[1 - i]
					self.player.rect.center = target.rect.center
					self.update_camera()
					self.teleported = True
					return True
		
		return False

	def collect_pistol(self, current_time):
		if not self.player or not self.pistols:
			return False
		for i in range(len(self.pistols) - 1, -1, -1):
			if self.player.rect.colliderect(self.pistols[i].rect):
				if not self.player.has_pistol:
					self.player.has_pistol = True
					self.player.ammo_in_clip = settings.PISTOL_MAX_AMMO
					self.player.total_ammo = 0
				else:
					self.player.total_ammo += settings.PISTOL_MAX_AMMO  # Добавляем 7 патронов
				self.pistols.pop(i)  # Удаляем подобранный пистолет
				return True
		return False

def draw_coin_counter(surface, count, settings):
	"""Отрисовывает счётчик монет в виде квадрата"""
	x, y = settings.COIN_UI_POS
	coin_color = COIN_COLOR
	
	# Рисуем квадрат монеты
	coin_rect = pygame.Rect(x, y, settings.COIN_UI_SIZE, settings.COIN_UI_SIZE)
	pygame.draw.rect(surface, coin_color, coin_rect)
	
	# Рисуем количество
	font = game_font
	text = font.render(f"{count}", True, (255, 255, 255))
	text_rect = text.get_rect(midright=(coin_rect.left - 10, coin_rect.centery))
	surface.blit(text, text_rect)

def main():
	# Инициализация
	language = russian
	title = TitleAnimation()
	button = Button(WIDTH//2, HEIGHT//2 + 100, language["play"], 50, 15)
	language_button = Button(WIDTH//2, HEIGHT//2 + 170, language["switch"], 50, 15)

	squares = [create_square() for _ in range(settings.SQUARES_COUNT)]
	in_menu = True
	in_game = False
	spawn_timer = 0
	MAX_SQUARES = 50

	try:
		synth = Synth()
		sfx = SFX(synth)
	except Exception as e:
		print(f"Ошибка инициализации звука: {e}")
		sfx = None
	
	current_level = 0
	levels = [Level0, Level1, Level2, Level3, Level4, Level5, Level6, Level7, Level8, Level9, Level10, Level11, Level12]
	level_drawer = None
	
	play_mp3_from_base64(MUSIC_B64)
	
	coins = 0
	freq_coins = 800
	coins_at_level_start = 0

	running = True
	while running:
		dt = clock.tick(60) / 1000.0
		mouse_pos = pygame.mouse.get_pos()
		current_time = time.time()  # Определяем current_time здесь
		
		for event in pygame.event.get():
			if event.type == pygame.QUIT:
				running = False
			
			if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1 and in_menu:
				if button.check_hover(mouse_pos):
					sfx.play("click_sound")
					in_menu = False
					in_game = True
					if current_level == 0:
						coins = 0
					else:
						coins = coins_at_level_start
					level_drawer = LevelDrawer(levels[current_level], language, current_level)
				
				elif language_button.check_hover(mouse_pos):
					sfx.play("click_sound")
					language = english if language == russian else russian
					button.text = language["play"]
					language_button.text = language["switch"]
					button.update_text(WIDTH//2, HEIGHT//2 + 100)
					language_button.update_text(WIDTH//2, HEIGHT//2 + 170)
					if in_game and level_drawer:
						level_drawer = LevelDrawer(levels[current_level], language, current_level)
					pygame.time.delay(200)
			
			if event.type == pygame.KEYDOWN:
				if event.key == pygame.K_ESCAPE:
					if in_game:
						sfx.play("exit_sound")
						in_game = False
						in_menu = True
						freq_coins = 800
						coins = coins_at_level_start
					else:
						pygame.quit()
				elif event.key == pygame.K_g:
					squares.clear()
				elif event.key == pygame.K_SPACE and in_game:
					if level_drawer.player.shoot(level_drawer.player_bullets, current_time):
						sfx.play("pistol_shot")
				elif event.key == pygame.K_r and in_game:
					level_drawer.player.reload(current_time)

		screen.fill((0, 0, 0))
		
		s = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
		s.fill((0, 0, 0, settings.BACKGROUND_ALPHA))
		screen.blit(s, (0, 0))
		
		spawn_timer += dt
		if spawn_timer >= settings.SPAWN_INTERVAL and len(squares) < MAX_SQUARES:
			squares.append(create_square())
			spawn_timer = 0
		
		for i in range(len(squares)-1, -1, -1):
			if not update_square(squares[i]):
				squares.pop(i)
			else:
				draw_square(screen, squares[i])

		if sfx:
			sfx.update()

		if in_game:
			keys = pygame.key.get_pressed()
			level_drawer.handle_input(keys, dt)
			draw_coin_counter(screen, coins, settings)
			
			level_drawer.update_gameplay(dt)
			level_drawer.player.update_reload(current_time)  # Добавляем обновление перезарядки
			
			if level_drawer.check_win():
				current_level += 1
				if current_level < len(levels):
					sfx.play("win_sound")
					sfx.update()
					level_drawer = LevelDrawer(levels[current_level], language, current_level)
					coins_at_level_start = coins
					freq_coins = 800
				else:
					sfx.play("victory_sound")
					in_game = False
					in_menu = True
					current_level = 0
			elif level_drawer.death() or level_drawer.check_bullet_collision():
				death = Death(language)
				if sfx:
					sfx.play("death_sound")
					sfx.update()
				death.run()
				level_drawer = LevelDrawer(levels[current_level], language, current_level)
				coins = coins_at_level_start
				freq_coins = 800
			elif level_drawer.collect_coin():
				coins += 1
				coin_sound = synth.generate_wave("WaveType.PULSE_25", freq_coins, 0.05, 0.2, 0.5)
				coin_sound.play()
				freq_coins *= 1.07
				if freq_coins > 3000:
					freq_coins = 800
			elif level_drawer.check_teleport():
				sfx.play("teleport_sound")
			elif level_drawer.collect_key():
				sfx.play("key_sound")
			elif level_drawer.collect_pistol(current_time):
				sfx.play("pistol_pickup")
			
			level_drawer.draw(screen, current_level)

			if level_drawer.player.has_pistol:
				ammo_text = game_font.render(f"{level_drawer.player.ammo_in_clip}/{level_drawer.player.total_ammo}", 
											True, (255, 255, 255))
				screen.blit(ammo_text, (30, HEIGHT - 40))
				for i in range(level_drawer.player.ammo_in_clip):
					pygame.draw.rect(screen, PISTOL_BULLET_COLOR, 
								   (90 + i * 15, HEIGHT - 30, 10, 10))

		elif in_menu:
			title.update()
			title.draw(screen)
			button.check_hover(mouse_pos)
			language_button.check_hover(mouse_pos)
			button.draw(screen)
			language_button.draw(screen)

			menu_comment_surface = game_font.render("Made by KTILTED. Press G if there are lags!", True, (255, 255, 255))
			screen.blit(menu_comment_surface, (WIDTH - menu_comment_surface.get_width() - 20, HEIGHT - 50))
		
		pygame.display.flip()

if __name__ == "__main__":
	main()